"""Build the CMS email draft (to the applicant) .robot files from data/testcases_email_candidate.csv.

Run:  python tools/csv_to_robot_email_candidate.py [path/to/testcases_email_candidate.csv]

* Same idea as tools/csv_to_robot_dashboard.py: the CSV is the source of truth for ID, description,
  expected result and type. STEPS maps each ID to its keywords and file group.
* Writes tests/email_candidate/*.robot (the other test folders are not touched).
* Do not hand-edit the generated files; edit STEPS or resources/pages/email_candidate.resource instead.
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from csv_to_robot import read_cases, render_test  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
DEFAULT_CSV = ROOT / "data" / "testcases_email_candidate.csv"
OUT_DIR = ROOT / "tests" / "email_candidate"
PREFIX = "EC"

GROUPS = {
    "open": ("01_open", "Open the draft, top of the page and wrong ids"),
    "form": ("02_form", "The form: templates, default text, boxes and labels"),
    "summary": ("03_info_status", "Info panel and status after sending"),
    "validation": ("04_validation", "Refused forms (nothing is sent)"),
    "layout": ("05_keyboard_layout", "Keyboard and screen sizes"),
}
MANUAL_FILE = "99_manual"

# EC id -> (group, [steps])
STEPS = {
    "EC001": ("open", ["Candidate Draft Should Open From The Profile"]),
    "EC002": ("open", ["Candidate Heading And Subtitle Should Match"]),
    "EC003": ("open", ["Top Bar Should Show Brand And User", "Menu Texts Should Match"]),
    "EC004": ("open", ["Link Should Return To The Profile    ${ED_BACK_LINK}    ${ED_BACK_TEXT}"]),
    "EC005": ("open", ["Link Should Return To The Profile    ${ED_CANCEL}    ${ED_CANCEL_TEXT}"]),
    "EC006": ("open", ["Candidate Draft Should Ask For Login When Logged Out"]),
    "EC007": ("open", ["Unknown Applicant Candidate Draft Should Show Not Found    ${PF_FAKE_ID}"]),
    "EC008": ("open", ["Unknown Applicant Candidate Draft Should Show Not Found    ${PF_BAD_ID}"]),
    "EC009": ("open", ["Refresh Should Keep The Same Candidate Draft"]),
    "EC010": ("form", ["Form Section Should Be Titled"]),
    "EC011": ("form", ["Candidate Form Labels Should Match"]),
    "EC012": ("form", ["Template List Should Start With Interview"]),
    "EC013": ("form", ["Every Candidate Draft Should Pass    cand_template"]),
    "EC014": ("form", ["Every Candidate Draft Should Pass    cand_recipients"]),
    "EC015": ("form", ["Every Candidate Draft Should Pass    cand_subject"]),
    "EC016": ("form", ["Every Candidate Draft Should Pass    cand_body"]),
    "EC017": ("form", ["Every Template Should Fill The Draft"]),
    "EC018": ("form", ["Every Template Should Show Its Status After Sending"]),
    "EC019": ("form", ["Every Template Should Send The Right Status Value"]),
    "EC020": ("form", ["Changing Template Should Replace The Text"]),
    "EC021": ("form", ["Boxes Should Be Editable"]),
    "EC022": ("form", ["Clicking A Label Should Focus Its Box"]),
    "EC023": ("form", ["Every Candidate Draft Should Pass    opens"]),
    "EC024": ("form", ["Every Candidate Draft Should Pass    cand_title"]),
    "EC025": ("form", ["Candidate Draft Should Have No Attachment Section"]),
    "EC026": ("summary", ["Candidate Info Panel Should Be Titled"]),
    "EC027": ("summary", ["Every Candidate Draft Should Pass    cand_info"]),
    "EC028": ("summary", ["Candidate Status After Sending Should Be Shown"]),
    "EC029": ("summary", ["Every Candidate Draft Should Pass    cand_status"]),
    "EC030": ("summary", ["Turning Off The Candidate Status Update Should Be Remembered"]),
    "EC031": ("summary", ["Turning Off The Update Should Hide The Template Status"]),
    "EC032": ("summary", ["Send Buttons Should Be Ready"]),
    "EC033": ("validation", ["Empty To Should Be Refused"]),
    "EC034": ("validation", ["Spaces Only To Should Be Refused"]),
    "EC035": ("validation", ["Wrong To Should Be Refused"]),
    "EC036": ("validation", ["Empty Subject Should Be Refused"]),
    "EC037": ("validation", ["Empty Body Should Be Refused"]),
    "EC038": ("validation", ["Wrong Cc Should Be Flagged"]),
    "EC039": ("validation", ["Boxes Should Keep What Was Typed After A Refusal"]),
    "EC040": ("layout", ["Candidate Tab Order Should Follow The Page"]),
    "EC041": ("layout", ["Info Panel Should Sit Beside The Form"]),
    "EC042": ("layout", ["Info Panel Should Sit Below The Form    768    1024"]),
    "EC043": ("layout", ["Page Should Not Scroll Sideways    375    812"]),
}

# Behaviour read from the dev site (or an expectation of mine) that the team must confirm.
ASSUMPTION_IDS = {"EC020", "EC025", "EC038", "EC039", "EC040", "EC041", "EC042"}


def file_header(title, ids, manual=False):
    out = ["*** Settings ***",
           f"Documentation     {title} ({ids[0]} to {ids[-1]}). GENERATED by tools/csv_to_robot_email_candidate.py - do not edit."]
    if manual:
        out += ["Test Tags         manual"]
    else:
        out += ["Resource          ../../resources/all_pages.resource",
                "Suite Setup       Open Candidate Browser",
                "Suite Teardown    Close All Browsers",
                "Test Setup        Open Candidate Draft",
                "Test Tags         automate    email-candidate    needs-account"]
    return "\n".join(out) + "\n\n\n*** Test Cases ***\n"


def main():
    csv_path = Path(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_CSV
    cases = read_cases(csv_path, PREFIX)
    auto = [c for c in cases if c["type"] == "automate"]
    manual = [c for c in cases if c["type"] == "manual"]

    missing = [c["id"] for c in auto if c["id"] not in STEPS]
    extra = [i for i in STEPS if i not in {c["id"] for c in auto}]
    if missing or extra:
        sys.exit(f"STEPS mismatch. In CSV as automate but no steps: {missing}. Steps but not automate in CSV: {extra}")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for old in OUT_DIR.glob("*.robot"):
        old.unlink()

    by_group = {g: [] for g in GROUPS}
    for case in auto:
        group, steps = STEPS[case["id"]]
        tags = [case["id"], group]
        if case["id"] in ASSUMPTION_IDS:
            tags.append("assumption")
        by_group[group].append(render_test(case, steps, tags))

    for group, (filename, title) in GROUPS.items():
        tests = by_group[group]
        ids = [t.split()[0] for t in tests]
        body = file_header(title, ids) + "\n\n".join(tests) + "\n"
        (OUT_DIR / f"{filename}.robot").write_text(body, encoding="utf-8", newline="\n")

    manual_tests = [
        render_test(c, ["Skip    Manual case: run by hand and record the result in the CSV"], [c["id"], "manual"])
        for c in manual
    ]
    ids = [c["id"] for c in manual]
    body = file_header("Manual cases (always skipped)", ids, manual=True) + "\n\n".join(manual_tests) + "\n"
    (OUT_DIR / f"{MANUAL_FILE}.robot").write_text(body, encoding="utf-8", newline="\n")

    print(f"automate: {len(auto)}  manual: {len(manual)}  total: {len(cases)}")
    for group, (filename, _) in GROUPS.items():
        print(f"  email_candidate/{filename}.robot  {len(by_group[group])}")
    print(f"  email_candidate/{MANUAL_FILE}.robot  {len(manual)}")


if __name__ == "__main__":
    main()
